const input = $input.first()?.json ?? {};
const query = String(input.query ?? input.query_text ?? '').trim();
if (!query) throw new Error('query is required');
const method = String(input.graphrag_method ?? input.method ?? 'global').trim().toLowerCase();
if (!['global', 'local', 'drift', 'basic'].includes(method)) throw new Error('unsupported GraphRAG method');
return [{ json: {
  query,
  method,
  response_type: String(input.response_type ?? 'Multiple paragraphs'),
  community_level: Number.isInteger(input.community_level) ? input.community_level : 2,
  dynamic_community_selection: Boolean(input.dynamic_community_selection),
  tenant_id: String(input.tenant_id ?? 'default').trim() || 'default',
} }];

const request = $('构建 GraphRAG 文献问题').first().json;
const response = $input.first()?.json ?? {};
const contexts = Array.isArray(response.contexts) ? response.contexts : [];
const citations = Array.isArray(response.citations) ? response.citations : contexts.map((item) => ({ citation_id: item.citation_id, title: item.title, source_url: item.source_url, page_start: item.page_start ?? null, page_end: item.page_end ?? null, source_locator: item.source_locator ?? '' }));
const status = String(response.status ?? 'success');
const warnings = Array.isArray(response.warnings) ? response.warnings.map((item) => String(item ?? '')).filter(Boolean) : [];
return [{ json: {
  query: request.query,
  contexts,
  citations,
  answer: String(response.answer ?? ''),
  warnings,
  retrieval: { ...(response.retrieval && typeof response.retrieval === 'object' ? response.retrieval : {}), status, engine: 'microsoft_graphrag', method: request.method, source_read: 'GraphRAG context mapped to original PDF locators' },
} }];
